// Build-time srcset helper driven by src/data/image-manifest.json
// (generated by scripts/gen-image-variants.mjs).
import manifest from "../data/image-manifest.json";

interface Entry {
  "400": number;
  "800": number;
  full: number;
}

export function imgSrcset(src: string): string | undefined {
  const name = src.replace("/images/", "").replace(".webp", "");
  const entry = (manifest as Record<string, Entry>)[name];
  if (!entry) return undefined;
  const base = src.replace(".webp", "");
  return [`${base}-400.webp ${entry["400"]}w`, `${base}-800.webp ${entry["800"]}w`, `${src} ${entry.full}w`].join(", ");
}
